tower.algebraic-limit-even-charge:
"""tower.algebraic-limit-even-charge: exact checks of the finite core.

The direct limit itself is infinite; what is checked is every finite square that builds it, at
the stages k = 0, 1, 2. Floors T_k = Cl(p+k, q+k) in GA.py (ground generators first, then the
planes e_j (+1), f_j (-1)); A = Cl(p,q). The identification phi_k : T_k -> A (x) Mat_{2^k} is
inverted by the nested Peirce dictionary of Theorem tower.commuting-copies: a matrix with entries
a_{IJ} in A (indices I = (i_k, ..., i_1), i = 1 the occupied and 2 the empty state, so that
E_11 = v w, E_12 = v, E_21 = w, E_22 = w v, the k-th plane outermost) goes to
sum E^k_{i_k 1} ( ... sum alpha_k(a_{IJ}) E^1_{i_1 j_1} ... ) E^k_{1 j_k}, with alpha_k the twisted
embedding (odd ground elements times Omega_k). Checked:
(1) Lemma tower.compatibility-connecting-maps-transported at the stages used: the tower inclusion
    iota_k equals phi_{k+1}^{-1} o Ad(V_k) o theta_k o phi_k on a basis of A (x) Mat_{2^k},
    V_k = diag(u_A (x) 1, 1 (x) Omega_k-bar), for A = Cl(1,1), Cl(2,0) (k = 0, 1, 2) and Cl(1,3)
    (k = 0, 1); and the same corrector fails for the odd-charge ground Cl(1,0).
(2) The theorem's intertwiners: W_0 = 1, W_{k+1} = theta_k(W_k) V_k^{-1}; then
    Ad(W_{k+1}) phi_{k+1} iota_k = theta_k Ad(W_k) phi_k on a basis of T_k: the tower embeddings
    become the block doublings m -> diag(m, m) exactly, stage by stage, so the two direct systems
    are isomorphic (their limit is A (x) Mat_{2^infinity} by definition).
(3) The second description: iota_k is the inclusion of the Clifford algebra of
    R^{p,q} + H_1 + ... + H_k into that of the next space (generators to generators, squares kept),
    and dim T_k = dim A * 4^k.
"""
from fractions import Fraction as F
from itertools import combinations, product

import GA
from tp_premise import premise

# ---------------------------------------------------------------------------
# Exact Clifford helpers on top of GA.py (elements are dicts {blade: Fraction}).
# ---------------------------------------------------------------------------


def blade_el(b, c=1):
    return {tuple(b): F(c)} if c else {}


def prod(xs, sq):
    out = GA.sc(1)
    for x in xs:
        out = GA.mul(out, x, sq)
    return out


def coords(x, n):
    return [x.get(b, F(0)) for b in GA.all_blades(n)]


def span_rank(els, n):
    els = [e for e in els if not GA.is_zero(e)]
    return GA.rank_of_vectors([coords(e, n) for e in els]) if els else 0


def words(gens, sq):
    """The ordered products of all subsets of gens: they span the generated subalgebra
    when the generators pairwise anticommute and square to nonzero scalars."""
    out = []
    for r in range(len(gens) + 1):
        for idx in combinations(range(len(gens)), r):
            out.append(prod([gens[i] for i in idx], sq))
    return out


def scalar_of(x):
    """x as a scalar if it is one, else None."""
    if GA.is_zero(x):
        return F(0)
    if set(x) == {()}:
        return x[()]
    return None


def anticommuting_with_squares(gens, sq):
    """The list of squares if the gens pairwise anticommute and square to scalars, else None."""
    out = []
    for i, g in enumerate(gens):
        s = scalar_of(GA.mul(g, g, sq))
        if s is None:
            return None
        out.append(s)
        for h in gens[i + 1:]:
            if not GA.anticommutes(g, h, sq):
                return None
    return out


def volume(n, sq):
    return prod([GA.gen(i) for i in range(n)], sq)


def is_central(x, n, sq):
    return all(GA.commutes(x, GA.gen(i), sq) for i in range(n))


def corner(f, basis, sq, n):
    """An independent spanning list of f b f, b in basis."""
    out, vecs = [], []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if GA.is_zero(y):
            continue
        v = coords(y, n)
        if GA.rank_of_vectors(vecs + [v]) > len(vecs):
            vecs.append(v)
            out.append(y)
    return out


def corner_division_type(f, basis, sq, n):
    """'R', 'C' or 'H' when f is an idempotent whose corner f A f is that division algebra
    (exact: R = span{f}; C = f plus an element squaring to -f; H = quaternion units i, j,
    i j with i^2 = j^2 = -f, i j = -j i), else None. A division corner makes f primitive,
    so the letter is the Wedderburn division algebra of the simple algebra A."""
    if not GA.eq(GA.mul(f, f, sq), f):
        return None
    cb = corner(f, basis, sq, n)
    if len(cb) == 1:
        return "R"
    roots = []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if not GA.is_zero(y) and GA.eq(GA.mul(y, y, sq), GA.neg(f)):
            roots.append(y)
    if len(cb) == 2 and roots:
        return "C"
    if len(cb) == 4:
        for i, a in enumerate(roots):
            for c in roots[i + 1:]:
                if GA.is_zero(GA.add(GA.mul(a, c, sq), GA.mul(c, a, sq))):
                    if span_rank([f, a, c, GA.mul(a, c, sq)], n) == 4:
                        return "H"
    return None


def idempotent_from(us, sq):
    """prod (1 + u)/2 over commuting elements u with u^2 = 1."""
    f = GA.sc(1)
    for u in us:
        f = GA.mul(f, GA.scal(F(1, 2), GA.add(GA.sc(1), u)), sq)
    return f


def simple_copy_type(gens, sq, n):
    """For a simple subalgebra spanned by words(gens): (k, D) with the subalgebra Mat_k(D),
    found from an idempotent f = prod (1 + u)/2 (u words squaring to 1, commuting) whose corner
    is a division algebra; dim = k^2 dim D is asserted. None if no such f is found."""
    basis = words(gens, sq)
    dim = span_rank(basis, n)
    units = [u for u in basis if scalar_of(u) is None and GA.eq(GA.mul(u, u, sq), GA.sc(1))]
    trials = [[]] + [[u] for u in units]
    trials += [[u, v] for i, u in enumerate(units) for v in units[i + 1:] if GA.commutes(u, v, sq)]
    for us in trials:
        f = idempotent_from(us, sq)
        if GA.is_zero(f):
            continue
        d = corner_division_type(f, basis, sq, n)
        if d is None:
            continue
        dd = {"R": 1, "C": 2, "H": 4}[d]
        k = 1
        while k * k * dd < dim:
            k += 1
        assert k * k * dd == dim
        return (k, d)
    return None
# ---------------------------------------------------------------------------
# Floors of the tower in GA.py: T_k over Cl(p,q) has the ground generators 0..n-1 (p squares +1,
# then q squares -1) and plane j (0-based) at n + 2j (e_j, square +1), n + 2j + 1 (f_j, square -1).
# v_j = (e_j + f_j)/2, w_j = (e_j - f_j)/2, omega_j = e_j f_j, Omega_k = omega_1 ... omega_k.
# ---------------------------------------------------------------------------


def floor_sq(p, q, k):
    return tuple([1] * p + [-1] * q + [1, -1] * k)


def plane(n, j):
    e, f = GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1)
    return GA.scal(F(1, 2), GA.add(e, f)), GA.scal(F(1, 2), GA.sub(e, f))


def big_omega(n, k, sq):
    return prod([GA.mul(GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1), sq) for j in range(k)], sq)


def twisted_ground(n, k, sq):
    Om = big_omega(n, k, sq)
    return [GA.mul(GA.gen(i), Om, sq) for i in range(n)]


def matrix_units(n, k, sq):
    """E[(S, T)] = v_S f v_T^dagger, S, T subsets of the k planes, f = prod_j w_j v_j the vacuum
    projector and v_T^dagger the reversed product of the w's; the Fock-basis matrix units of B_k."""
    vs, ws = zip(*[plane(n, j) for j in range(k)]) if k else ((), ())
    f = prod([GA.mul(ws[j], vs[j], sq) for j in range(k)], sq)
    subsets = [S for r in range(k + 1) for S in combinations(range(k), r)]
    E = {}
    for S in subsets:
        left = prod([vs[j] for j in S], sq)
        for T in subsets:
            right = prod([ws[j] for j in reversed(T)], sq)
            E[(S, T)] = GA.mul(GA.mul(left, f, sq), right, sq)
    return subsets, E


def matrix_units_ok(subsets, E, sq):
    one = GA.add(*[E[(S, S)] for S in subsets])
    if not GA.eq(one, GA.sc(1)):
        return False
    for (S, T), x in E.items():
        for (U, W), y in E.items():
            want = E[(S, W)] if T == U else {}
            if not GA.eq(GA.mul(x, y, sq), want):
                return False
    return True


def tensor_blades(gens_a, gens_b, sq):
    """Products of the ordered words of gens_a with those of gens_b, when every one is a single
    basis blade: the set of blades hit (None if some product is not a single blade)."""
    seen = set()
    for a in words(gens_a, sq):
        for b in words(gens_b, sq):
            x = GA.mul(a, b, sq)
            if len(x) != 1:
                return None
            seen.add(next(iter(x)))
    return seen

EVEN_GROUNDS = [((1, 1), 2), ((2, 0), 2), ((1, 3), 1)]   # (signature, highest k checked)


def ground_basis(n):
    return [blade_el(b) for b in GA.all_blades(n)]


def alpha(a, Om, sq):
    out = {}
    for b, c in a.items():
        piece = {b: c} if len(b) % 2 == 0 else GA.mul({b: c}, Om, sq)
        out = GA.add(out, piece)
    return out


def units_of_plane(n, j, sq):
    v, w = plane(n, j)
    return {(1, 1): GA.mul(v, w, sq), (1, 2): v, (2, 1): w, (2, 2): GA.mul(w, v, sq)}


def phi_inv(M, n, k, sq):
    """M: {(I, J): ground element}, I, J tuples (i_k, ..., i_1); returns the element of T_k."""
    if k == 0:
        return M.get(((), ()), {})
    Om = big_omega(n, k, sq)
    Es = [units_of_plane(n, j, sq) for j in range(k)]

    def level(m, outer_I, outer_J):
        # the block of M with fixed outer indices, expanded over planes m-1, ..., 0
        if m == 0:
            return alpha(M.get((outer_I, outer_J), {}), Om, sq)
        out = {}
        if m == 1:
            for i1 in (1, 2):
                for j1 in (1, 2):
                    a = M.get((outer_I + (i1,), outer_J + (j1,)))
                    if a:
                        out = GA.add(out, GA.mul(alpha(a, Om, sq), Es[0][(i1, j1)], sq))
            return out
        E = Es[m - 1]
        for im in (1, 2):
            for jm in (1, 2):
                inner = level(m - 1, outer_I + (im,), outer_J + (jm,))
                if inner:
                    out = GA.add(out, GA.mul(GA.mul(E[(im, 1)], inner, sq), E[(1, jm)], sq))
        return out

    return level(k, (), ())


def idx(k):
    return list(product((1, 2), repeat=k))


def theta(M):
    out = {}
    for (I, J), a in M.items():
        for o in (1, 2):
            out[((o,) + I, (o,) + J)] = a
    return out


def diag_mul(D, M, sq, left=True):
    """D diagonal {I: element}; returns D M (left) or M D (right)."""
    out = {}
    for (I, J), a in M.items():
        x = GA.mul(D[I], a, sq) if left else GA.mul(a, D[J], sq)
        if not GA.is_zero(x):
            out[(I, J)] = x
    return out


def corrector(n, k, sq):
    """V_k = diag(u_A (x) 1, 1 (x) Omega_k-bar) and its inverse, as diagonals over (i_{k+1}, I)."""
    uA = prod([GA.gen(i) for i in range(n)], sq)
    u2 = scalar_of(GA.mul(uA, uA, sq))
    V, Vi = {}, {}
    for I in idx(k + 1):
        if I[0] == 1:
            V[I], Vi[I] = uA, GA.scal(1 / u2, uA)
        else:
            s = 1
            for i in I[1:]:
                s = -s if i == 1 else s
            V[I], Vi[I] = GA.sc(s), GA.sc(s)
    return V, Vi


def basis_matrices(n, k):
    out = []
    for a in ground_basis(n):
        for I in idx(k):
            for J in idx(k):
                out.append({(I, J): a})
    return out


def transported_ok(p, q, k):
    n = p + q
    sq = floor_sq(p, q, k + 1)
    V, Vi = corrector(n, k, sq)
    ok = True
    for M in basis_matrices(n, k):
        lhs = phi_inv(M, n, k, sq)
        rhs = phi_inv(diag_mul(Vi, diag_mul(V, theta(M), sq), sq, left=False), n, k + 1, sq)
        ok = ok and GA.eq(lhs, rhs)
    return ok


def check_transported_connecting_map_is_corrected_doubling():
    premise("tower.commuting-copies")
    premise("tower.compatibility-connecting-maps-transported")
    ok = True
    for (p, q), kmax in EVEN_GROUNDS:
        for k in range(kmax + 1):
            ok = ok and transported_ok(p, q, k)
    # control: odd charge, the ground volume is central and the corrector does not work
    ok = ok and not transported_ok(1, 0, 0) and not transported_ok(1, 0, 1)
    GA.check("iota_k = phi_{k+1}^{-1} Ad(V_k) theta_k phi_k for even charge (k <= 2); fails for Cl(1,0)", ok)
    return ok


def check_intertwiners_make_the_embeddings_block_doublings():
    premise("tower.commuting-copies")
    premise("tower.compatibility-connecting-maps-transported")
    ok = True
    for (p, q), kmax in EVEN_GROUNDS:
        n = p + q
        W = {(): GA.sc(1)}
        Wi = {(): GA.sc(1)}
        for k in range(kmax + 1):
            sq = floor_sq(p, q, k + 1)
            V, Vi = corrector(n, k, sq)
            W1 = {I: GA.mul(W[I[1:]], Vi[I], sq) for I in idx(k + 1)}       # theta(W_k) V_k^{-1}
            W1i = {I: GA.mul(V[I], Wi[I[1:]], sq) for I in idx(k + 1)}
            ok = ok and all(GA.eq(GA.mul(W1[I], W1i[I], sq), GA.sc(1)) for I in idx(k + 1))
            for M in basis_matrices(n, k):
                # t = Lambda_k^{-1}(M) = phi_k^{-1}(W_k^{-1} M W_k); want Lambda_{k+1}(t) = theta(M)
                t = phi_inv(diag_mul(Wi, diag_mul(W, M, sq, left=False), sq), n, k, sq)
                s = phi_inv(diag_mul(W1i, diag_mul(W1, theta(M), sq, left=False), sq), n, k + 1, sq)
                ok = ok and GA.eq(s, t) and not GA.is_zero(t)
            W, Wi = W1, W1i
    GA.check("with W_{k+1} = theta(W_k) V_k^{-1} the tower embeddings are the block doublings, k <= 2", ok)
    return ok


def check_limit_is_clifford_algebra_of_the_union():
    premise("tower.commuting-copies")
    ok = True
    for (p, q), kmax in EVEN_GROUNDS:
        n = p + q
        for k in range(kmax + 1):
            sq_k, sq_k1 = floor_sq(p, q, k), floor_sq(p, q, k + 1)
            ok = ok and sq_k1[:len(sq_k)] == sq_k and sq_k1[len(sq_k):] == (1, -1)
            # products of the generators of T_k are the same in T_{k+1}: iota_k is the inclusion
            gens = [GA.gen(i) for i in range(n + 2 * k)]
            ok = ok and all(GA.eq(GA.mul(a, b, sq_k), GA.mul(a, b, sq_k1)) for a in gens for b in gens)
            ok = ok and len(GA.all_blades(n + 2 * k)) == len(ground_basis(n)) * 4 ** k
    GA.check("iota_k is the inclusion of Clifford algebras of the nested quadratic spaces", ok)
    return ok

tower.answers-iteration-question:
"""tower.answers-iteration-question: exact checks of the computable clauses.

Clause 1 (one forced ascent on the physical side, one rung per shadow wall beyond it) is a
statement about the geometry of a tame degeneration (Fact tower.wall-package) with no finite
algebraic core here, and is not checked. Clauses 2 and 3 are checked on the physical tower
Cl(1+k, 3+k) in GA.py (ground generators first, then plane j as e_j (+1), f_j (-1)):
(2) the clock never ticks: the charge (1+k) - (3+k) mod 8 is 6 at every floor; the centre of each
    floor k = 0, 1, 2 is R (blade-wise, exhaustive, valid for diagonal forms), so no floor has a
    central idempotent; and each floor is Mat_{2^(k+1)}(H), read off the idempotent
    f = (1 + e_0)/2 prod_j w_j v_j whose corner f T_k f is a quaternion algebra (a division corner,
    so f is primitive): the same division ring H at every floor, Morita-stationary;
(3) the fermionic ladder: the plane pairs give k CAR modes on floor k (k <= 3), one more per rung,
    and the Fock module of the modes doubles per rung (2^k states).
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from tp_premise import premise

# ---------------------------------------------------------------------------
# Exact Clifford helpers on top of GA.py (elements are dicts {blade: Fraction}).
# ---------------------------------------------------------------------------


def blade_el(b, c=1):
    return {tuple(b): F(c)} if c else {}


def prod(xs, sq):
    out = GA.sc(1)
    for x in xs:
        out = GA.mul(out, x, sq)
    return out


def coords(x, n):
    return [x.get(b, F(0)) for b in GA.all_blades(n)]


def span_rank(els, n):
    els = [e for e in els if not GA.is_zero(e)]
    return GA.rank_of_vectors([coords(e, n) for e in els]) if els else 0


def words(gens, sq):
    """The ordered products of all subsets of gens: they span the generated subalgebra
    when the generators pairwise anticommute and square to nonzero scalars."""
    out = []
    for r in range(len(gens) + 1):
        for idx in combinations(range(len(gens)), r):
            out.append(prod([gens[i] for i in idx], sq))
    return out


def scalar_of(x):
    """x as a scalar if it is one, else None."""
    if GA.is_zero(x):
        return F(0)
    if set(x) == {()}:
        return x[()]
    return None


def anticommuting_with_squares(gens, sq):
    """The list of squares if the gens pairwise anticommute and square to scalars, else None."""
    out = []
    for i, g in enumerate(gens):
        s = scalar_of(GA.mul(g, g, sq))
        if s is None:
            return None
        out.append(s)
        for h in gens[i + 1:]:
            if not GA.anticommutes(g, h, sq):
                return None
    return out


def volume(n, sq):
    return prod([GA.gen(i) for i in range(n)], sq)


def is_central(x, n, sq):
    return all(GA.commutes(x, GA.gen(i), sq) for i in range(n))


def corner(f, basis, sq, n):
    """An independent spanning list of f b f, b in basis."""
    out, vecs = [], []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if GA.is_zero(y):
            continue
        v = coords(y, n)
        if GA.rank_of_vectors(vecs + [v]) > len(vecs):
            vecs.append(v)
            out.append(y)
    return out


def corner_division_type(f, basis, sq, n):
    """'R', 'C' or 'H' when f is an idempotent whose corner f A f is that division algebra
    (exact: R = span{f}; C = f plus an element squaring to -f; H = quaternion units i, j,
    i j with i^2 = j^2 = -f, i j = -j i), else None. A division corner makes f primitive,
    so the letter is the Wedderburn division algebra of the simple algebra A."""
    if not GA.eq(GA.mul(f, f, sq), f):
        return None
    cb = corner(f, basis, sq, n)
    if len(cb) == 1:
        return "R"
    roots = []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if not GA.is_zero(y) and GA.eq(GA.mul(y, y, sq), GA.neg(f)):
            roots.append(y)
    if len(cb) == 2 and roots:
        return "C"
    if len(cb) == 4:
        for i, a in enumerate(roots):
            for c in roots[i + 1:]:
                if GA.is_zero(GA.add(GA.mul(a, c, sq), GA.mul(c, a, sq))):
                    if span_rank([f, a, c, GA.mul(a, c, sq)], n) == 4:
                        return "H"
    return None


def idempotent_from(us, sq):
    """prod (1 + u)/2 over commuting elements u with u^2 = 1."""
    f = GA.sc(1)
    for u in us:
        f = GA.mul(f, GA.scal(F(1, 2), GA.add(GA.sc(1), u)), sq)
    return f


def simple_copy_type(gens, sq, n):
    """For a simple subalgebra spanned by words(gens): (k, D) with the subalgebra Mat_k(D),
    found from an idempotent f = prod (1 + u)/2 (u words squaring to 1, commuting) whose corner
    is a division algebra; dim = k^2 dim D is asserted. None if no such f is found."""
    basis = words(gens, sq)
    dim = span_rank(basis, n)
    units = [u for u in basis if scalar_of(u) is None and GA.eq(GA.mul(u, u, sq), GA.sc(1))]
    trials = [[]] + [[u] for u in units]
    trials += [[u, v] for i, u in enumerate(units) for v in units[i + 1:] if GA.commutes(u, v, sq)]
    for us in trials:
        f = idempotent_from(us, sq)
        if GA.is_zero(f):
            continue
        d = corner_division_type(f, basis, sq, n)
        if d is None:
            continue
        dd = {"R": 1, "C": 2, "H": 4}[d]
        k = 1
        while k * k * dd < dim:
            k += 1
        assert k * k * dd == dim
        return (k, d)
    return None
# ---------------------------------------------------------------------------
# Floors of the tower in GA.py: T_k over Cl(p,q) has the ground generators 0..n-1 (p squares +1,
# then q squares -1) and plane j (0-based) at n + 2j (e_j, square +1), n + 2j + 1 (f_j, square -1).
# v_j = (e_j + f_j)/2, w_j = (e_j - f_j)/2, omega_j = e_j f_j, Omega_k = omega_1 ... omega_k.
# ---------------------------------------------------------------------------


def floor_sq(p, q, k):
    return tuple([1] * p + [-1] * q + [1, -1] * k)


def plane(n, j):
    e, f = GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1)
    return GA.scal(F(1, 2), GA.add(e, f)), GA.scal(F(1, 2), GA.sub(e, f))


def big_omega(n, k, sq):
    return prod([GA.mul(GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1), sq) for j in range(k)], sq)


def twisted_ground(n, k, sq):
    Om = big_omega(n, k, sq)
    return [GA.mul(GA.gen(i), Om, sq) for i in range(n)]


def matrix_units(n, k, sq):
    """E[(S, T)] = v_S f v_T^dagger, S, T subsets of the k planes, f = prod_j w_j v_j the vacuum
    projector and v_T^dagger the reversed product of the w's; the Fock-basis matrix units of B_k."""
    vs, ws = zip(*[plane(n, j) for j in range(k)]) if k else ((), ())
    f = prod([GA.mul(ws[j], vs[j], sq) for j in range(k)], sq)
    subsets = [S for r in range(k + 1) for S in combinations(range(k), r)]
    E = {}
    for S in subsets:
        left = prod([vs[j] for j in S], sq)
        for T in subsets:
            right = prod([ws[j] for j in reversed(T)], sq)
            E[(S, T)] = GA.mul(GA.mul(left, f, sq), right, sq)
    return subsets, E


def matrix_units_ok(subsets, E, sq):
    one = GA.add(*[E[(S, S)] for S in subsets])
    if not GA.eq(one, GA.sc(1)):
        return False
    for (S, T), x in E.items():
        for (U, W), y in E.items():
            want = E[(S, W)] if T == U else {}
            if not GA.eq(GA.mul(x, y, sq), want):
                return False
    return True


def tensor_blades(gens_a, gens_b, sq):
    """Products of the ordered words of gens_a with those of gens_b, when every one is a single
    basis blade: the set of blades hit (None if some product is not a single blade)."""
    seen = set()
    for a in words(gens_a, sq):
        for b in words(gens_b, sq):
            x = GA.mul(a, b, sq)
            if len(x) != 1:
                return None
            seen.add(next(iter(x)))
    return seen


def centre_blades(sq):
    m = len(sq)
    return [b for b in GA.all_blades(m) if all(GA.commutes(blade_el(b), GA.gen(i), sq) for i in range(m))]


def check_clock_never_ticks():
    premise("tower.rigidity-clock-frozen")
    ok = True
    types = []
    for k in (0, 1, 2):
        sq = floor_sq(1, 3, k)
        m = len(sq)
        ok = ok and ((1 + k) - (3 + k)) % 8 == 6
        ok = ok and centre_blades(sq) == [()]
        us = [GA.gen(0)]
        f = idempotent_from(us, sq)
        for j in range(k):
            v, w = plane(4, j)
            f = GA.mul(f, GA.mul(w, v, sq), sq)
        ok = ok and GA.eq(GA.mul(f, f, sq), f)
        basis = [blade_el(b) for b in GA.all_blades(m)]
        types.append((corner_division_type(f, basis, sq, m), f.get((), F(0))))
    # division ring H at every floor; trace of f = 1/(2 * 2^k): rank one of Mat_{2^(k+1)}(H)
    ok = ok and types == [("H", F(1, 2)), ("H", F(1, 4)), ("H", F(1, 8))]
    GA.check("physical tower: charge 6, centre R, Mat_{2^(k+1)}(H) at k = 0, 1, 2", ok)
    return ok


def check_one_qubit_per_rung():
    premise("tower.car-limit-even-charge")
    ok = True
    counts = []
    for k in (1, 2, 3):
        sq = floor_sq(1, 3, k)
        pairs = [plane(4, j) for j in range(k)]
        good = 0
        for i, (vi, wi) in enumerate(pairs):
            row = all(GA.is_zero(GA.add(GA.mul(vi, vj, sq), GA.mul(vj, vi, sq)))
                      and GA.eq(GA.add(GA.mul(vi, wj, sq), GA.mul(wj, vi, sq)), GA.sc(1) if i == j else {})
                      for j, (vj, wj) in enumerate(pairs))
            good += 1 if row else 0
        counts.append(good)
        # the Fock module of the modes: the 2^k wedge monomials of the creation vectors are independent
        vs = [v for v, w in pairs]
        mons = words(vs, sq)
        ok = ok and span_rank(mons, 4 + 2 * k) == 2 ** k
    ok = ok and counts == [1, 2, 3]
    GA.check("one CAR mode per rung and a Fock space doubling per rung on the physical tower", ok)
    return ok

tower.car-limit-even-charge:
"""tower.car-limit-even-charge: exact checks of the finite core.

The C*-completion and Glimm's and the CAR uniqueness theorems (Fact
tower.glimms-classification-car-uniqueness) have no finite content and are not recomputed. What
is checked, at finite stages: floors T_k in GA.py (ground generators first, then plane j as e_j
(+1), f_j (-1); v_j = (e_j + f_j)/2, w_j = (e_j - f_j)/2), the *-antiautomorphism with x* = x for
x^2 = 1 and x* = -x for x^2 = -1, and the Fock module Lambda W_k (occupation basis, orthonormal
wedge monomials, v_j by wedge, w_j by contraction).
(1) a_j = w_j, a_j^dagger = v_j satisfy the CAR exactly in T_k (k <= 3, grounds (1,3), (1,1),
    (0,0)), with a_j^dagger = a_j^* for the intrinsic *;
(2) Fock adjointness: the contraction by w_j is the transpose of the wedge by v_j for the inner
    product making the monomials orthonormal (k <= 4), the vacuum is annihilated by every a_j, and
    the *-relations are implemented by the adjoint: rho(x^*) = rho(x)^T for every blade x of the
    plane algebra B_k (k <= 3) and of the whole floor over the even ground (1,1), where rho is
    faithful onto End (rank 4^m), the *-isomorphism with Mat(2^(m/2)) and the transpose;
(3) the factors: the twisted ground generators commute with every a_j, a_j^dagger (grounds
    (1,3), (2,0), (1,1), k <= 2), the j-th plane's algebra is generated by its pair (the words of
    v_j, w_j span the four dimensions of span{1, e_j, f_j, e_j f_j}), and the correctors are
    unitary: the ground volume element u_A satisfies u_A^* u_A = 1 and the Omega_k^* Omega_k = 1.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from pyutil import get_or_set
from tp_premise import premise

# ---------------------------------------------------------------------------
# Exact Clifford helpers on top of GA.py (elements are dicts {blade: Fraction}).
# ---------------------------------------------------------------------------


def blade_el(b, c=1):
    return {tuple(b): F(c)} if c else {}


def prod(xs, sq):
    out = GA.sc(1)
    for x in xs:
        out = GA.mul(out, x, sq)
    return out


def coords(x, n):
    return [x.get(b, F(0)) for b in GA.all_blades(n)]


def span_rank(els, n):
    els = [e for e in els if not GA.is_zero(e)]
    return GA.rank_of_vectors([coords(e, n) for e in els]) if els else 0


def words(gens, sq):
    """The ordered products of all subsets of gens: they span the generated subalgebra
    when the generators pairwise anticommute and square to nonzero scalars."""
    out = []
    for r in range(len(gens) + 1):
        for idx in combinations(range(len(gens)), r):
            out.append(prod([gens[i] for i in idx], sq))
    return out


def scalar_of(x):
    """x as a scalar if it is one, else None."""
    if GA.is_zero(x):
        return F(0)
    if set(x) == {()}:
        return x[()]
    return None


def anticommuting_with_squares(gens, sq):
    """The list of squares if the gens pairwise anticommute and square to scalars, else None."""
    out = []
    for i, g in enumerate(gens):
        s = scalar_of(GA.mul(g, g, sq))
        if s is None:
            return None
        out.append(s)
        for h in gens[i + 1:]:
            if not GA.anticommutes(g, h, sq):
                return None
    return out


def volume(n, sq):
    return prod([GA.gen(i) for i in range(n)], sq)


def is_central(x, n, sq):
    return all(GA.commutes(x, GA.gen(i), sq) for i in range(n))


def corner(f, basis, sq, n):
    """An independent spanning list of f b f, b in basis."""
    out, vecs = [], []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if GA.is_zero(y):
            continue
        v = coords(y, n)
        if GA.rank_of_vectors(vecs + [v]) > len(vecs):
            vecs.append(v)
            out.append(y)
    return out


def corner_division_type(f, basis, sq, n):
    """'R', 'C' or 'H' when f is an idempotent whose corner f A f is that division algebra
    (exact: R = span{f}; C = f plus an element squaring to -f; H = quaternion units i, j,
    i j with i^2 = j^2 = -f, i j = -j i), else None. A division corner makes f primitive,
    so the letter is the Wedderburn division algebra of the simple algebra A."""
    if not GA.eq(GA.mul(f, f, sq), f):
        return None
    cb = corner(f, basis, sq, n)
    if len(cb) == 1:
        return "R"
    roots = []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if not GA.is_zero(y) and GA.eq(GA.mul(y, y, sq), GA.neg(f)):
            roots.append(y)
    if len(cb) == 2 and roots:
        return "C"
    if len(cb) == 4:
        for i, a in enumerate(roots):
            for c in roots[i + 1:]:
                if GA.is_zero(GA.add(GA.mul(a, c, sq), GA.mul(c, a, sq))):
                    if span_rank([f, a, c, GA.mul(a, c, sq)], n) == 4:
                        return "H"
    return None


def idempotent_from(us, sq):
    """prod (1 + u)/2 over commuting elements u with u^2 = 1."""
    f = GA.sc(1)
    for u in us:
        f = GA.mul(f, GA.scal(F(1, 2), GA.add(GA.sc(1), u)), sq)
    return f


def simple_copy_type(gens, sq, n):
    """For a simple subalgebra spanned by words(gens): (k, D) with the subalgebra Mat_k(D),
    found from an idempotent f = prod (1 + u)/2 (u words squaring to 1, commuting) whose corner
    is a division algebra; dim = k^2 dim D is asserted. None if no such f is found."""
    basis = words(gens, sq)
    dim = span_rank(basis, n)
    units = [u for u in basis if scalar_of(u) is None and GA.eq(GA.mul(u, u, sq), GA.sc(1))]
    trials = [[]] + [[u] for u in units]
    trials += [[u, v] for i, u in enumerate(units) for v in units[i + 1:] if GA.commutes(u, v, sq)]
    for us in trials:
        f = idempotent_from(us, sq)
        if GA.is_zero(f):
            continue
        d = corner_division_type(f, basis, sq, n)
        if d is None:
            continue
        dd = {"R": 1, "C": 2, "H": 4}[d]
        k = 1
        while k * k * dd < dim:
            k += 1
        assert k * k * dd == dim
        return (k, d)
    return None
# ---------------------------------------------------------------------------
# Floors of the tower in GA.py: T_k over Cl(p,q) has the ground generators 0..n-1 (p squares +1,
# then q squares -1) and plane j (0-based) at n + 2j (e_j, square +1), n + 2j + 1 (f_j, square -1).
# v_j = (e_j + f_j)/2, w_j = (e_j - f_j)/2, omega_j = e_j f_j, Omega_k = omega_1 ... omega_k.
# ---------------------------------------------------------------------------


def floor_sq(p, q, k):
    return tuple([1] * p + [-1] * q + [1, -1] * k)


def plane(n, j):
    e, f = GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1)
    return GA.scal(F(1, 2), GA.add(e, f)), GA.scal(F(1, 2), GA.sub(e, f))


def big_omega(n, k, sq):
    return prod([GA.mul(GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1), sq) for j in range(k)], sq)


def twisted_ground(n, k, sq):
    Om = big_omega(n, k, sq)
    return [GA.mul(GA.gen(i), Om, sq) for i in range(n)]


def matrix_units(n, k, sq):
    """E[(S, T)] = v_S f v_T^dagger, S, T subsets of the k planes, f = prod_j w_j v_j the vacuum
    projector and v_T^dagger the reversed product of the w's; the Fock-basis matrix units of B_k."""
    vs, ws = zip(*[plane(n, j) for j in range(k)]) if k else ((), ())
    f = prod([GA.mul(ws[j], vs[j], sq) for j in range(k)], sq)
    subsets = [S for r in range(k + 1) for S in combinations(range(k), r)]
    E = {}
    for S in subsets:
        left = prod([vs[j] for j in S], sq)
        for T in subsets:
            right = prod([ws[j] for j in reversed(T)], sq)
            E[(S, T)] = GA.mul(GA.mul(left, f, sq), right, sq)
    return subsets, E


def matrix_units_ok(subsets, E, sq):
    one = GA.add(*[E[(S, S)] for S in subsets])
    if not GA.eq(one, GA.sc(1)):
        return False
    for (S, T), x in E.items():
        for (U, W), y in E.items():
            want = E[(S, W)] if T == U else {}
            if not GA.eq(GA.mul(x, y, sq), want):
                return False
    return True


def tensor_blades(gens_a, gens_b, sq):
    """Products of the ordered words of gens_a with those of gens_b, when every one is a single
    basis blade: the set of blades hit (None if some product is not a single blade)."""
    seen = set()
    for a in words(gens_a, sq):
        for b in words(gens_b, sq):
            x = GA.mul(a, b, sq)
            if len(x) != 1:
                return None
            seen.add(next(iter(x)))
    return seen
# ---------------------------------------------------------------------------
# The Fock module Lambda W_k in the occupation basis: states are bitmasks 0 .. 2^k - 1, bit j set
# when v_j is present; the wedge monomial basis v_{j1} ^ ... ^ v_{jr} (j1 < ... < jr) is
# orthonormal. v_j acts by wedge (sign (-1)^(occupied modes below j)), w_j by contraction.
# Operators are sparse matrices {(row, col): Fraction}.
# ---------------------------------------------------------------------------


def k_wedge(j, k):
    return {(s | 1 << j, s): F((-1) ** bin(s & ((1 << j) - 1)).count("1"))
            for s in range(2 ** k) if not s >> j & 1}


def k_contract(j, k):
    return {(s & ~(1 << j), s): F((-1) ** bin(s & ((1 << j) - 1)).count("1"))
            for s in range(2 ** k) if s >> j & 1}


def smm(*Ms):
    out = Ms[0]
    for B in Ms[1:]:
        rows = {}
        for (r, c), x in B.items():
            get_or_set(rows, r, []).append((c, x))
        acc = {}
        for (r, t), x in out.items():
            for c, y in rows.get(t, ()):
                acc[(r, c)] = acc.get((r, c), 0) + x * y
        out = {key: v for key, v in acc.items() if v}
    return out


def sadd(*Ms):
    acc = {}
    for M in Ms:
        for key, x in M.items():
            acc[key] = acc.get(key, 0) + x
    return {key: v for key, v in acc.items() if v}


def ssc(c, A):
    return {key: c * x for key, x in A.items() if c * x}


def str_(A):
    return {(c, r): x for (r, c), x in A.items()}


def sident(d):
    return {(s, s): F(1) for s in range(d)}


def plane_images(k):
    """rho(e_j) = wedge + contraction, rho(f_j) = wedge - contraction, in GA generator order."""
    out = []
    for j in range(k):
        a, b = k_wedge(j, k), k_contract(j, k)
        out += [sadd(a, b), sadd(a, ssc(-1, b))]
    return out


def flat(M, d):
    return [M.get((r, c), F(0)) for r in range(d) for c in range(d)]

CAR_GROUNDS = [(1, 3), (1, 1), (0, 0)]
# numbers of rungs k on which the CAR is checked
CAR_RUNGS = (1, 2, 3)
TWIST_GROUNDS = [(1, 3), (2, 0), (1, 1)]


def star_blade(b, sq):
    out = GA.sc(1)
    for i in reversed(b):
        out = GA.mul(out, GA.scal(sq[i], GA.gen(i)), sq)
    return out


def star(x, sq):
    return GA.add(*[GA.scal(c, star_blade(b, sq)) for b, c in x.items()]) if x else {}


def rho_of(x, images, d):
    out = {}
    for b, c in x.items():
        out = sadd(out, ssc(c, smm(*([sident(d)] + [images[i] for i in b]))))
    return out


def check_tower_vectors_satisfy_the_car():
    premise("tower.ladder-pairs-satisfy-car-vectors")
    premise("tower.structure-tower-c-norms")
    ok = True
    for p, q in CAR_GROUNDS:
        for k in CAR_RUNGS:
            sq = floor_sq(p, q, k)
            pairs = [plane(p + q, j) for j in range(k)]
            a = [w for v, w in pairs]
            ad = [v for v, w in pairs]
            for i in range(k):
                ok = ok and GA.eq(star(a[i], sq), ad[i])
                for j in range(k):
                    ok = ok and GA.is_zero(GA.add(GA.mul(a[i], a[j], sq), GA.mul(a[j], a[i], sq)))
                    ok = ok and GA.is_zero(GA.add(GA.mul(ad[i], ad[j], sq), GA.mul(ad[j], ad[i], sq)))
                    ac = GA.add(GA.mul(a[i], ad[j], sq), GA.mul(ad[j], a[i], sq))
                    ok = ok and GA.eq(ac, GA.sc(1) if i == j else {})
    GA.check("a_j = w_j, a_j^dagger = v_j = a_j^*: the CAR exactly, k <= 3", ok)
    return ok


def check_fock_adjointness():
    premise("tower.fock-module-one-qubit-per-rung")
    premise("tower.structure-tower-c-norms")
    ok = True
    for k in (1, 2, 3, 4):
        vac = {(0, 0): F(1)}
        for j in range(k):
            ok = ok and k_contract(j, k) == str_(k_wedge(j, k)) and not smm(k_contract(j, k), vac)
            ok = ok and bool(smm(k_wedge(j, k), vac))
    for k in (1, 2, 3):
        d = 2 ** k
        imgs = plane_images(k)
        sq = floor_sq(0, 0, k)
        for b in GA.all_blades(2 * k):
            x = blade_el(b)
            ok = ok and rho_of(star(x, sq), imgs, d) == str_(rho_of(x, imgs, d))
    # the whole floor over (1,1), the ground pair as one more mode: faithful onto End, * = transpose
    for k in (0, 1, 2):
        m = 2 + 2 * k
        d = 2 ** (m // 2)
        imgs = plane_images(m // 2)
        sq = floor_sq(1, 1, k)
        flats = []
        for b in GA.all_blades(m):
            x = blade_el(b)
            r = rho_of(x, imgs, d)
            ok = ok and rho_of(star(x, sq), imgs, d) == str_(r)
            flats.append(flat(r, d))
        ok = ok and GA.rank_of_vectors(flats) == d * d == 4 ** (m // 2)
    GA.check("contraction is the adjoint of wedge, vacuum killed by every a_j, rho(x*) = rho(x)^T", ok)
    return ok


def check_ground_factor_commutes_and_correctors_unitary():
    premise("tower.algebraic-limit-even-charge")
    premise("tower.structure-tower-c-norms")
    ok = True
    for p, q in TWIST_GROUNDS:
        n = p + q
        for k in (1, 2):
            sq = floor_sq(p, q, k)
            tw = twisted_ground(n, k, sq)
            pairs = [plane(n, j) for j in range(k)]
            ok = ok and all(GA.commutes(x, y, sq) for x in tw for v, w in pairs for y in (v, w))
            for j, (v, w) in enumerate(pairs):
                e, f = GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1)
                ok = ok and span_rank(words([v, w], sq), n + 2 * k) == 4
                ok = ok and span_rank(words([v, w], sq) + words([e, f], sq), n + 2 * k) == 4
            Om = big_omega(n, k, sq)
            ok = ok and GA.eq(GA.mul(star(Om, sq), Om, sq), GA.sc(1))
        uA = prod([GA.gen(i) for i in range(n)], floor_sq(p, q, 0))
        ok = ok and GA.eq(GA.mul(star(uA, floor_sq(p, q, 0)), uA, floor_sq(p, q, 0)), GA.sc(1))
    GA.check("ground factor commutes with the modes; plane algebra generated by its pair; correctors unitary", ok)
    return ok

tower.compatibility-connecting-maps-tran:
"""tower.compatibility-connecting-maps-transported: exact checks.

GA.py blade engine. Floor T_k over the ground A = Cl(p,q) (p - q even): ground generators at
0..n-1, plane j at n+2(j-1) (e_j, +1), n+2j-1 (f_j, -1); v_j = (e_j+f_j)/2, w_j = (e_j-f_j)/2;
matrix units of plane j labelled as in Fact transport.rule-1-morita-trivial: E11 = v w, E12 = v,
E21 = w, E22 = w v. Omega_k = omega_1...omega_k. The identification phi_k^{-1} : A (x) Mat_{2^k} -> T_k
of tower.commuting-copies, planes nested in order with plane k carrying the outer index:
    phi_k^{-1}(a (x) E_{I,J}) = E_k[i_k,1] ( ... E_1[i_1,1] alpha_k(a) E_1[1,j_1] ... ) E_k[1,j_k],
alpha_k(a) = a on even blades and a Omega_k on odd blades (the twisted ground copy). A matrix over
A is a dict {(I, J): ground element}, I and J tuples (outer index first).
(1) The data: phi_k^{-1} is multiplicative on matrix units and sends 1 (x) Omega-bar_k (the diagonal
    with entry prod_j s(i_j), s(1) = -1, s(2) = +1) to Omega_k, and u_A (x) Omega-bar_k to the floor's
    volume element u_{T_k}; V_k is invertible (V_k V_k^-1 = 1, u_A^2 = +-1).
(2) The lemma: phi_{k+1}^{-1}(Ad(V_k) theta_k(z)) = phi_k^{-1}(z) (computed in T_{k+1}) for EVERY
    basis element z = a (x) E_{I,J} (a a ground blade), for the grounds Cl(0,0), Cl(1,1), Cl(2,0),
    Cl(0,2) at k = 1, 2 and Cl(1,3), Cl(3,1), Cl(2,2) at k = 1, with
    V_k = diag(u_A (x) 1, 1 (x) Omega-bar_k).
(3) The naive transported single-step corrector diag(1, u_A (x) Omega-bar_k) (the image of
    diag(1, u_{T_k})) fails on some basis element for every ground with n >= 2 here; for the trivial
    ground n = 0 (u_A = 1) it coincides with V_k. The labelling matters: with vw and wv exchanged for
    the new plane, V_k fails, the bare exchange of corners diag(1 (x) Omega-bar_k, u_A (x) 1) fails too,
    and the corrector that works is diag(1, u_A (x) Omega-bar_k), the transported single-step one
    (reported: the statement's "exchanges the two corners of V_k" is not what the computation gives).
EXPORTS: Tower (phi_k^{-1}, alpha_k, the matrix units), idx, omega_bar, theta, corrector, conj_diag.
"""
from fractions import Fraction as F
from itertools import product

import GA
from tp_premise import premise

CASES = [((0, 0), 1), ((0, 0), 2), ((1, 1), 1), ((1, 1), 2), ((2, 0), 1), ((2, 0), 2), ((0, 2), 1),
         ((0, 2), 2), ((1, 3), 1), ((3, 1), 1), ((2, 2), 1)]


class Tower(object):
    def __init__(self, p, q, kmax, swap=()):
        self.n = n = p + q
        self.S = tuple([1] * p + [-1] * q + [1, -1] * kmax)
        S = self.S
        self.E = []
        self.om = []
        for j in range(kmax):
            e, f = GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1)
            v, w = GA.scal(F(1, 2), GA.add(e, f)), GA.scal(F(1, 2), GA.sub(e, f))
            if j in swap:
                v, w = w, v
            self.E.append({(1, 1): GA.mul(v, w, S), (1, 2): v, (2, 1): w, (2, 2): GA.mul(w, v, S)})
            self.om.append(GA.mul(e, f, S))
        self.uA = {tuple(range(n)): F(1)}

    def mul(self, *xs):
        out = GA.sc(1)
        for x in xs:
            out = GA.mul(out, x, self.S)
        return out

    def Om(self, k):
        return self.mul(*self.om[:k])

    def alpha(self, a, k):
        Om = self.Om(k)
        out = {}
        for b, c in a.items():
            piece = {b: c} if len(b) % 2 == 0 else GA.mul({b: c}, Om, self.S)
            out = GA.add(out, piece)
        return out

    def phi_inv(self, M, k):
        out = {}
        for (I, J), a in M.items():
            x = self.alpha(a, k)
            for lvl in range(k):          # inner plane first: index k-1-lvl of the tuples
                j = lvl
                i_, l_ = I[k - 1 - lvl], J[k - 1 - lvl]
                x = self.mul(self.E[j][(i_, 1)], x, self.E[j][(1, l_)])
            out = GA.add(out, x)
        return out


def idx(k):
    return list(product((1, 2), repeat=k))


def omega_bar(I):
    s = 1
    for i in I:
        s *= -1 if i == 1 else 1
    return F(s)


def conj_diag(Vd, Vinv, N, S):
    out = {}
    for (K, L), a in N.items():
        z = GA.mul(GA.mul(Vd[K], a, S), Vinv[L], S)
        if z:
            out[(K, L)] = z
    return out


def theta(M):
    return {((o,) + I, (o,) + J): a for (I, J), a in M.items() for o in (1, 2)}


def inv_pm1(u, S):
    return u if GA.eq(GA.mul(u, u, S), GA.sc(1)) else GA.neg(u)


def corrector(T, k, first_ground):
    """diag(u_A (x) 1, 1 (x) Omega-bar_k) if first_ground, else diag(1 (x) Omega-bar_k, u_A (x) 1)."""
    S = T.S
    uinv = inv_pm1(T.uA, S)
    V, Vi = {}, {}
    for o in (1, 2):
        for I in idx(k):
            K = (o,) + I
            ground_corner = (o == 1) == first_ground
            V[K] = T.uA if ground_corner else GA.sc(omega_bar(I))
            Vi[K] = uinv if ground_corner else GA.sc(omega_bar(I))
    return V, Vi


def naive(T, k):
    S = T.S
    uinv = inv_pm1(T.uA, S)
    V, Vi = {}, {}
    for o in (1, 2):
        for I in idx(k):
            K = (o,) + I
            V[K] = GA.sc(1) if o == 1 else GA.scal(omega_bar(I), T.uA)
            Vi[K] = GA.sc(1) if o == 1 else GA.scal(omega_bar(I), uinv)
    return V, Vi


def basis(T, k):
    for a in GA.all_blades(T.n):
        for I in idx(k):
            for J in idx(k):
                yield {(I, J): {a: F(1)}}


def holds(T, k, V, Vi):
    for z in basis(T, k):
        lhs = T.phi_inv(z, k)
        rhs = T.phi_inv(conj_diag(V, Vi, theta(z), T.S), k + 1)
        if not GA.eq(lhs, rhs):
            return False
    return True


EXPORTS = {"Tower": Tower, "idx": idx, "omega_bar": omega_bar, "theta": theta,
           "corrector": corrector, "conj_diag": conj_diag}


def check_identification_data():
    premise("tower.commuting-copies")
    premise("tower.volume-elements-planes")
    for (p, q), k in CASES:
        T = Tower(p, q, k + 1)
        S = T.S
        units = [(I, J) for I in idx(k) for J in idx(k)]
        for (I, J) in units:
            for (K, L) in units:
                prod_ = GA.mul(T.phi_inv({(I, J): GA.sc(1)}, k), T.phi_inv({(K, L): GA.sc(1)}, k), S)
                want = T.phi_inv({(I, L): GA.sc(1)}, k) if J == K else {}
                assert GA.eq(prod_, want)
        Ob = {(I, I): GA.sc(omega_bar(I)) for I in idx(k)}
        assert GA.eq(T.phi_inv(Ob, k), T.Om(k))
        uT = {tuple(range(T.n + 2 * k)): F(1)}
        assert GA.eq(T.phi_inv({(I, I): GA.scal(omega_bar(I), T.uA) for I in idx(k)}, k), uT)
        u2 = GA.mul(T.uA, T.uA, S)
        assert GA.eq(u2, GA.sc(1)) or GA.eq(u2, GA.sc(-1))
        V, Vi = corrector(T, k, True)
        assert all(GA.eq(GA.mul(V[K], Vi[K], S), GA.sc(1)) for K in V)
    return True


def check_transported_connecting_map_is_ad_v_theta():
    premise("tower.grade-twist-when-it-inner")
    premise("transport.rule-1-morita-trivial")
    for (p, q), k in CASES:
        assert (p - q) % 2 == 0
        T = Tower(p, q, k + 1)
        V, Vi = corrector(T, k, True)
        assert holds(T, k, V, Vi), ((p, q), k)
    return True


# grounds on which the exchanged labelling of the outer plane is also tested
SWAP_GROUNDS = ((1, 1), (2, 0), (1, 3))


def tower_to_next_floor(p, q, k, **kw):
    """The tower through floor k + 1, where the connecting map at rung k lands."""
    return Tower(p, q, k + 1, **kw)


def check_naive_corrector_and_labelling_convention():
    for (p, q), k in CASES:
        T = tower_to_next_floor(p, q, k)
        V, Vi = naive(T, k)
        if p + q == 0:
            assert holds(T, k, V, Vi)
        else:
            assert not holds(T, k, V, Vi), ((p, q), k)
        if (p, q) in SWAP_GROUNDS:
            # exchange vw and wv for the outer (new) plane: the ground volume moves to the second
            # corner, where it joins the planes' volume; the bare exchange of corners fails
            Ts = tower_to_next_floor(p, q, k, swap=(k,))
            Vn, Vni = naive(Ts, k)
            assert holds(Ts, k, Vn, Vni)
            Vx, Vxi = corrector(Ts, k, False)
            assert not holds(Ts, k, Vx, Vxi)
            V0, V0i = corrector(Ts, k, True)
            assert not holds(Ts, k, V0, V0i)
    return True

tower.fock-module-one-qubit-per-rung:
"""tower.fock-module-one-qubit-per-rung: exact checks.

Lambda W_k is modelled on subsets S of {0..k-1} (a basis state is the wedge of the v_j, j in S, in
increasing order), with v_j acting by wedge and w_j by contraction (Koszul signs). The plane
generators act as e_j = v_j + w_j and f_j = v_j - w_j. Everything is exact.
(1) W_k is maximal isotropic (computed in GA.py inside Cl(k,k), k <= 4): the v_j are independent,
    pairwise orthogonal and null, and the orthogonal complement of W_k has dimension k (so it is W_k).
(2) The Chevalley action is a module of B_k = Cl(k,k) (k <= 4): on every basis state e_j^2 = 1,
    f_j^2 = -1 and distinct generators anticommute; c(a)^2 = Q(a) for a general vector a. The
    vacuum is killed by every w_j, the creation monomials applied to it give all 2^k states (rank 2^k),
    and dim Lambda W_k = 2^k.
(3) Irreducibility: for k <= 3 the 4^k blades of B_k act by matrices of rank 4^k = dim End(Lambda W_k)
    (so B_k = Mat_{2^k}(R) acts fully); for k <= 4 also by the Fock criterion: the common kernel of
    the w_j is the vacuum line (dimension 1), and the vacuum is cyclic.
(4) Doubling: Lambda W_{k+1} has dimension 2 * 2^k, with basis S and S + {k}, and the operators of the
    first k planes act on it as (old operator) (x) id (computed on every basis state), while v_k, w_k
    change only the new slot (with the parity sign of the old part): one qubit per rung.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from tp_premise import premise

KMAX = 4


def states(k):
    return [frozenset(c) for r in range(k + 1) for c in combinations(range(k), r)]


def wedge(j, st):
    out = {}
    for S, c in st.items():
        if j in S:
            continue
        T = frozenset(S | {j})
        out[T] = out.get(T, F(0)) + (-1) ** len([i for i in S if i < j]) * c
    return {S: c for S, c in out.items() if c != 0}


def contract(j, st):
    out = {}
    for S, c in st.items():
        if j not in S:
            continue
        T = frozenset(S - {j})
        out[T] = out.get(T, F(0)) + (-1) ** len([i for i in S if i < j]) * c
    return {S: c for S, c in out.items() if c != 0}


def add(*xs):
    out = {}
    for x in xs:
        for S, c in x.items():
            out[S] = out.get(S, F(0)) + c
    return {S: c for S, c in out.items() if c != 0}


def scal(c, x):
    return {S: c * v for S, v in x.items() if c * v != 0}


def act(gen, st):
    """gen = ('e', j) or ('f', j) or ('v', j) or ('w', j)."""
    t, j = gen
    if t == "v":
        return wedge(j, st)
    if t == "w":
        return contract(j, st)
    if t == "e":
        return add(wedge(j, st), contract(j, st))
    return add(wedge(j, st), scal(-1, contract(j, st)))


def act_word(word, st):
    for g in reversed(word):
        st = act(g, st)
    return st


def gens(k):
    return [(t, j) for j in range(k) for t in ("e", "f")]


# the numbers of rungs k checked
RUNGS = range(1, KMAX + 1)
# full-matrix-algebra test (4^k blades) up to this k (time)
FULL_ACTION_KMAX = 3
# the vacuum state (empty wedge)
VACUUM = {frozenset(): F(1)}


def basis_state(S):
    """The basis state of Lambda W_k labelled by the subset S."""
    return {S: F(1)}


def sample_vector(k):
    """Coefficients (alpha_j, beta_j) of a sample general vector a = sum alpha_j e_j + beta_j f_j."""
    return [F(2 * j + 1, 3) for j in range(k)], [F(1 - j, 2) for j in range(k)]


def ordered_words(G):
    """All increasing words in the generator list G (one per blade)."""
    return [w for r in range(len(G) + 1) for w in combinations(G, r)]


def check_w_is_maximal_isotropic():
    premise("tower.ladder-pairs-satisfy-car-vectors")
    for k in range(1, KMAX + 1):
        S = tuple([1, -1] * k)
        vs = [GA.scal(F(1, 2), GA.add(GA.gen(2 * j), GA.gen(2 * j + 1))) for j in range(k)]
        vecs = [[v.get((i,), F(0)) for i in range(2 * k)] for v in vs]
        assert GA.rank_of_vectors(vecs) == k
        for a in vs:
            for b in vs:
                assert GA.dot(a, b, S) == 0
        # orthogonal complement of W in R^(k,k): kernel of the k x 2k matrix of <v_j, e_i>
        M = [[GA.dot(v, GA.gen(i), S) for i in range(2 * k)] for v in vs]
        assert 2 * k - GA.rank_of_vectors(M) == k
    return True


def check_chevalley_module_and_vacuum():
    for k in RUNGS:
        sts = states(k)
        assert len(sts) == 2 ** k
        for S in sts:
            st = basis_state(S)
            for g in gens(k):
                want = st if g[0] == "e" else scal(-1, st)
                assert act_word([g, g], st) == want
                for h in gens(k):
                    if h != g:
                        assert add(act_word([g, h], st), act_word([h, g], st)) == {}
            # a general vector a = sum (alpha_j e_j + beta_j f_j): c(a)^2 = Q(a) = sum alpha^2 - beta^2
            al, be = sample_vector(k)

            def ca(x):
                return add(*[scal(al[j], act(("e", j), x)) for j in range(k)]
                           + [scal(be[j], act(("f", j), x)) for j in range(k)])
            Qa = sum(a * a for a in al) - sum(b * b for b in be)
            assert ca(ca(st)) == scal(Qa, st)
        vac = VACUUM
        for j in range(k):
            assert act(("w", j), vac) == {}
        imgs = [act_word([("v", j) for j in sorted(S)], vac) for S in sts]
        assert GA.rank_of_vectors([[x.get(T, F(0)) for T in sts] for x in imgs]) == 2 ** k
    return True


def check_irreducible():
    premise("tower.commuting-copies")
    for k in RUNGS:
        sts = states(k)
        if k <= FULL_ACTION_KMAX:
            mats = []
            for word in ordered_words(gens(k)):
                row = []
                for S in sts:
                    img = act_word(list(word), basis_state(S))
                    row.extend(img.get(T, F(0)) for T in sts)
                mats.append(row)
            assert len(mats) == 4 ** k
            assert GA.rank_of_vectors(mats) == 4 ** k
        # Fock criterion: common kernel of the contractions is the vacuum line
        rows = []
        for j in range(k):
            for T in sts:
                rows.append([act(("w", j), basis_state(S)).get(T, F(0)) for S in sts])
        assert 2 ** k - GA.rank_of_vectors(rows) == 1
        assert all(act(("w", j), VACUUM) == {} for j in range(k))
    return True


def check_one_qubit_per_rung():
    for k in range(1, KMAX):
        small, big = states(k), states(k + 1)
        assert len(big) == 2 * len(small)
        new = frozenset([k])
        assert set(big) == set(small) | {S | new for S in small}
        for S in small:
            for T in (frozenset(), new):
                for g in gens(k):
                    lhs = act(g, {S | T: F(1)})
                    rhs = {U | T: c for U, c in act(g, {S: F(1)}).items()}
                    assert lhs == rhs
                par = (-1) ** len(S)
                # the new pair moves only the new slot, with the parity sign of the old part
                assert act(("v", k), {S: F(1)}) == {S | new: F(par)}
                assert act(("w", k), {S | new: F(1)}) == {S: F(par)}
                assert act(("v", k), {S | new: F(1)}) == {} and act(("w", k), {S: F(1)}) == {}
    return True

tower.grade-twist-when-it-inner:
"""tower.grade-twist-when-it-inner: exact checks.

GA.py blade engine, ground Cl(p,q) at indices 0..n-1 and the new plane (e, f) after it, with the
ladder pair v = (e+f)/2, w = (e-f)/2 and the matrix units of Fact transport.rule-1-morita-trivial,
E11 = v w, E22 = w v, E12 = v, E21 = w (so E11 = (1 - e f)/2).
(1) The matrix form of the tower embedding: for every ground with n <= 4, every basis blade a of the
    base, read through the corner identification (entry c_ij defined by c_ij E11 = E1i a Ej1), has
    the matrix diag(a, a^) (a^ the grade involution): the twisted diagonal. In the twisted-copy
    coordinates of tower.commuting-copies with the same labelling (a ground generator x read as
    x omega = x^(1) times omega = 1 (x) diag(-1, 1)) the same embedding reads diag(a^, a); the order of
    the two corners is the labelling convention that tower.compatibility-connecting-maps-transported
    records (exchanging vw and wv exchanges them).
(2) Even n (every signature with n <= 6): the volume element u anticommutes with every generator,
    u^2 = +-1, and u a u^-1 = a^ on every basis blade; U diag(a, a) U^-1 = diag(a, a^) with
    U = diag(1, u) on sample elements (2 x 2 matrices with Clifford entries). For odd n <= 7, u
    commutes with every generator instead.
(3) Innerness exactly when n is even: the space of g with g x = -x g for every generator x (the
    elements implementing the grade involution, together with 0) is R u for even n <= 6 and {0}
    for odd n <= 5, computed as an exact kernel. For odd n <= 7 the centre is span{1, omega}
    (blade-wise), and the grade involution sends omega to -omega: it moves the centre, so it is outer.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

SIGS = [(p, n - p) for n in range(1, 8) for p in range(n + 1)]
SAMPLE = {(): F(2), (0,): F(1), (0, 1): F(3), (1,): F(-1, 5), (0, 1, 2): F(4, 7)}


def sample_in(n):
    return {b: c for b, c in SAMPLE.items() if all(i < n for i in b)}


def vol(n):
    return {tuple(range(n)): F(1)}


def inv_pm1(u, S):
    u2 = GA.mul(u, u, S)
    return u if GA.eq(u2, GA.sc(1)) else GA.neg(u)


def m22(A, B, S):
    return [[GA.add(GA.mul(A[i][0], B[0][j], S), GA.mul(A[i][1], B[1][j], S)) for j in range(2)]
            for i in range(2)]


def check_embedding_is_twisted_diagonal():
    premise("transport.rule-1-morita-trivial")
    for p, q in [(p, n - p) for n in range(5) for p in range(n + 1)]:
        n = p + q
        S = GA.sig(p, q) + (1, -1)
        e, f = GA.gen(n), GA.gen(n + 1)
        v, w = GA.scal(F(1, 2), GA.add(e, f)), GA.scal(F(1, 2), GA.sub(e, f))
        E = {(1, 1): GA.mul(v, w, S), (2, 2): GA.mul(w, v, S), (1, 2): v, (2, 1): w}
        assert GA.eq(E[(1, 1)], GA.scal(F(1, 2), GA.sub(GA.sc(1), GA.mul(e, f, S))))
        for a_b in GA.all_blades(n):
            a = {a_b: F(1)}
            for i in (1, 2):
                for j in (1, 2):
                    m = GA.mul(GA.mul(E[(1, i)], a, S), E[(j, 1)], S)
                    # m = c E11 with c in the base: c is twice the part of m free of plane letters
                    c = {b: 2 * x for b, x in m.items() if n not in b and n + 1 not in b}
                    assert GA.eq(GA.mul(c, E[(1, 1)], S), m)
                    want = {} if i != j else (a if i == 1 else GA.grade_inv(a))
                    assert GA.eq(c, want), ((p, q), a_b, i, j)
            # twisted-copy coordinates: odd x = (x omega) omega, omega = E22 - E11 = diag(-1, 1)
            om = GA.mul(e, f, S)
            assert GA.eq(om, GA.sub(E[(2, 2)], E[(1, 1)]))
            if len(a_b) % 2 == 1:
                assert GA.eq(GA.mul(GA.mul(a, om, S), om, S), a)
    return True


def check_even_charge_volume_element_implements_twist():
    for p, q in SIGS:
        n = p + q
        S = GA.sig(p, q)
        u = vol(n)
        u2 = GA.mul(u, u, S)
        assert GA.eq(u2, GA.sc(1)) or GA.eq(u2, GA.sc(-1))
        uinv = inv_pm1(u, S)
        for i in range(n):
            x = GA.gen(i)
            if n % 2 == 0:
                assert GA.anticommutes(u, x, S)
            else:
                assert GA.commutes(u, x, S) and not GA.anticommutes(u, x, S)
        if n % 2 == 0 and n <= 6:
            for b in GA.all_blades(n):
                a = {b: F(1)}
                assert GA.eq(GA.mul(GA.mul(u, a, S), uinv, S), GA.grade_inv(a))
            a = sample_in(n)
            U = [[GA.sc(1), {}], [{}, u]]
            Ui = [[GA.sc(1), {}], [{}, uinv]]
            got = m22(m22(U, [[a, {}], [{}, a]], S), Ui, S)
            want = [[a, {}], [{}, GA.grade_inv(a)]]
            assert all(GA.eq(got[i][j], want[i][j]) for i in range(2) for j in range(2))
    return True


def check_inner_exactly_for_even_charge():
    for p, q in SIGS:
        n = p + q
        S = GA.sig(p, q)
        blades = GA.all_blades(n)
        if n <= 6:
            # unknown g = sum g_B B; equations: g x + x g = 0 for every generator x
            cols = []
            for B in blades:
                col = []
                for i in range(n):
                    x = GA.gen(i)
                    z = GA.add(GA.mul({B: F(1)}, x, S), GA.mul(x, {B: F(1)}, S))
                    col.extend(z.get(bb, F(0)) for bb in blades)
                cols.append(col)
            rows = [[cols[c][r] for c in range(len(blades))] for r in range(len(cols[0]))]
            ker = GA.field_kernel(rows)
            if n % 2 == 0:
                assert len(ker) == 1
                kv = ker[0]
                nz = [blades[i] for i in range(len(blades)) if kv[i] != 0]
                assert nz == [tuple(range(n))]
            elif n <= 5:
                assert len(ker) == 0
        if n % 2 == 1:
            central = [b for b in blades
                       if all(GA.commutes({b: F(1)}, GA.gen(i), S) for i in range(n))]
            assert central == [(), tuple(range(n))]
            om = vol(n)
            assert GA.eq(GA.grade_inv(om), GA.neg(om)) and not GA.eq(GA.grade_inv(om), om)
    return True

tower.ladder-pairs-satisfy-car-vectors:
"""tower.ladder-pairs-satisfy-car-vectors: exact checks.

Floor T_k = Cl(p+k, q+k) in GA.py's blade engine with the tower layout (ground generators first,
then plane j as e_j (square +1), f_j (square -1)); the normalised null pair of plane j is
v_j = (e_j + f_j)/2, w_j = (e_j - f_j)/2. For every ground (p,q) with n <= 3 and every k <= 3:
(1) the CAR hold as vector identities: v_i v_j + v_j v_i = 0, w_i w_j + w_j w_i = 0,
    v_i w_j + w_j v_i = delta_ij, for all i, j <= k; the inputs behind them are computed too:
    Q(v_i) = Q(w_i) = 0, <v_i, w_i> = 1/2, vectors of distinct planes orthogonal;
(2) adding a rung: in T_{k+1} the new pair anticommutes with every ground generator and every
    generator of the earlier planes (it is orthogonal to them), and every relation among the first
    k pairs, recomputed in T_{k+1}, gives the same element as in T_k.
No representation is used: every relation is a product of multivectors.
"""
from fractions import Fraction as F

import GA

GROUNDS = [(p, n - p) for n in range(4) for p in range(n + 1)]
KMAX = 3


def floor(p, q, k):
    return tuple([1] * p + [-1] * q + [1, -1] * k)


def pairs(n, k):
    vs, ws = [], []
    for j in range(k):
        e, f = GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1)
        vs.append(GA.scal(F(1, 2), GA.add(e, f)))
        ws.append(GA.scal(F(1, 2), GA.sub(e, f)))
    return vs, ws


def anti(a, b, S):
    return GA.add(GA.mul(a, b, S), GA.mul(b, a, S))


def check_car_as_vectors():
    for p, q in GROUNDS:
        n = p + q
        for k in range(1, KMAX + 1):
            S = floor(p, q, k)
            vs, ws = pairs(n, k)
            for i in range(k):
                assert GA.dot(vs[i], vs[i], S) == 0 and GA.dot(ws[i], ws[i], S) == 0
                assert GA.dot(vs[i], ws[i], S) == F(1, 2)
                for j in range(k):
                    assert GA.is_zero(anti(vs[i], vs[j], S))
                    assert GA.is_zero(anti(ws[i], ws[j], S))
                    want = GA.sc(1) if i == j else {}
                    assert GA.eq(anti(vs[i], ws[j], S), want), ((p, q), k, i, j)
                    if i != j:
                        for a in (vs[i], ws[i]):
                            for b in (vs[j], ws[j]):
                                assert GA.dot(a, b, S) == 0
    return True


def check_new_rung_touches_nothing():
    for p, q in GROUNDS:
        n = p + q
        for k in range(KMAX):
            S, S1 = floor(p, q, k), floor(p, q, k + 1)
            vs, ws = pairs(n, k)
            vs1, ws1 = pairs(n, k + 1)
            vn, wn = vs1[k], ws1[k]
            earlier = [GA.gen(i) for i in range(n + 2 * k)]
            for g in earlier:
                assert GA.is_zero(anti(vn, g, S1)) and GA.is_zero(anti(wn, g, S1))
            assert GA.eq(anti(vn, wn, S1), GA.sc(1))
            for i in range(k):
                for j in range(k):
                    for a, b in ((vs[i], vs[j]), (ws[i], ws[j]), (vs[i], ws[j])):
                        assert GA.eq(anti(a, b, S), anti(a, b, S1))
    return True

tower.matrix-amplification-structural-pr:
"""tower.matrix-amplification-structural-properties: exact checks.

Unital real algebras A are realised exactly as Clifford algebras with the blade engine:
Cl(0,1) = C, Cl(0,2) = H, Cl(1,0) = R + R, Cl(1,1) = Mat_2(R), Cl(0,3) = H + H. Matrices over A are
sparse dicts {(i, j): element}.
  (i)   Z(Mat_m(A)) is computed by exact linear algebra (kernel of the commutators with every
        E_ij 1 and every a 1_m, a a generator of A) and compared with Z(A) 1_m, for five A and
        m = 2, 3;
  (ii)  for A simple (C, H, Mat_2(R)) the two-sided ideal of Mat_2(A) generated by sample nonzero
        elements is all of Mat_2(A) (rank m^2 dim A); control: for A = R + R the ideal generated by
        eps_+ E_11 is proper;
  (iii) the block flattening Phi: Mat_m(Mat_r(D)) -> Mat_mr(D) is a bijection on bases and
        multiplicative on every pair of basis elements, for (m, r, D) = (2, 2, H), (2, 3, C),
        (3, 2, R + R), with the dimensions written out;
  (iv)  for A = A1 + A2 split by a central idempotent (Cl(0,3) = H + H, Cl(1,0) = R + R) the map
        X -> (eps_+ X, eps_- X) is multiplicative on every pair of basis elements of Mat_2(A),
        injective, and onto Mat_2(eps_+ A) + Mat_2(eps_- A), each summand of the stated dimension,
        eps_+ H-part satisfying the quaternion relations.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise  # noqa: F401  (self-contained lemma: no premises)


def alg(p, q):
    sq = GA.sig(p, q)
    return sq, GA.all_blades(p + q)


def mmul(X, Y, sq):
    out = {}
    for (i, k), a in X.items():
        for (k2, j), b in Y.items():
            if k == k2:
                c = GA.mul(a, b, sq)
                if c:
                    out[(i, j)] = GA.add(out.get((i, j), {}), c)
    return {ij: c for ij, c in out.items() if c}


def msub(X, Y):
    out = dict(X)
    for ij, c in Y.items():
        out[ij] = GA.sub(out.get(ij, {}), c)
    return {ij: c for ij, c in out.items() if c}


def mcoords(X, m, blades):
    return [X.get((i, j), {}).get(b, F(0)) for i in range(m) for j in range(m) for b in blades]


def mbasis(m, blades):
    return [{(i, j): {b: F(1)}} for i in range(m) for j in range(m) for b in blades]


def ident(m, a=None):
    a = GA.sc(1) if a is None else a
    return {(i, i): a for i in range(m)}


def centre_of_matrices(m, sq, blades):
    n = len(sq)
    tests = [{(i, j): GA.sc(1)} for i in range(m) for j in range(m)]
    tests += [ident(m, GA.gen(g)) for g in range(n)]
    basis = mbasis(m, blades)
    rows = []
    for T in tests:
        cols = [mcoords(msub(mmul(T, B, sq), mmul(B, T, sq)), m, blades) for B in basis]
        rows.extend([cols[c][r] for c in range(len(basis))] for r in range(len(cols[0])))
    return GA.field_kernel(rows)


def centre_of_alg(sq, blades):
    n = len(sq)
    rows = []
    for g in range(n):
        cols = []
        for b in blades:
            c = GA.sub(GA.mul(GA.gen(g), {b: F(1)}, sq), GA.mul({b: F(1)}, GA.gen(g), sq))
            cols.append([c.get(bb, F(0)) for bb in blades])
        rows.extend([cols[c][r] for c in range(len(blades))] for r in range(len(blades)))
    if not rows:
        return [[F(1)]]
    return GA.field_kernel(rows)


def check_centre_of_matrix_algebra():
    # (p, q) of A, dim Z(A)
    algebras = [((0, 1), 2), ((0, 2), 1), ((1, 0), 2), ((1, 1), 1), ((1, 2), 2)]
    ok = True
    for (p, q), zdim in algebras:
        sq, blades = alg(p, q)
        ZA = centre_of_alg(sq, blades)
        ok = ok and len(ZA) == zdim
        for m in (2, 3):
            ZM = centre_of_matrices(m, sq, blades)
            ok = ok and len(ZM) == zdim
            # every z 1_m (z in Z(A)) is in the computed centre: span unchanged
            emb = []
            for z in ZA:
                zel = {b: c for b, c in zip(blades, z) if c != 0}
                emb.append(mcoords(ident(m, zel), m, blades))
            ok = ok and GA.field_rank(ZM + emb) == zdim
    GA.check("Z(Mat_m(A)) = Z(A) 1_m for five A and m = 2, 3", ok)
    return ok


def ideal_dim(x, m, sq, blades):
    basis = mbasis(m, blades)
    span = []
    for L in basis:
        Lx = mmul(L, x, sq)
        if not Lx:
            continue
        for R in basis:
            y = mmul(Lx, R, sq)
            if y:
                span.append(mcoords(y, m, blades))
    return GA.field_rank(span)


def sample_elements(n):
    """Three nonzero elements of Mat_2(A) of different shapes."""
    return [{(0, 0): GA.sc(1)},
            {(0, 1): GA.add(GA.sc(3), GA.gen(0)), (1, 1): GA.gen(n - 1)},
            {(1, 0): GA.scal(F(1, 2), GA.add(GA.sc(1), GA.gen(0)))}]


def check_matrix_algebra_over_simple_is_simple():
    ok = True
    m = 2
    # (p, q) of A, dim Mat_2(A)
    for (p, q), dimM in (((0, 1), 8), ((0, 2), 16), ((1, 1), 16)):
        sq, blades = alg(p, q)
        for x in sample_elements(p + q):
            ok = ok and ideal_dim(x, m, sq, blades) == dimM
    # control: A = R + R is not simple, and neither is Mat_2(A): eps_+ E_11 generates Mat_2(R)
    sq, blades = alg(1, 0)
    ep = GA.scal(F(1, 2), GA.add(GA.sc(1), GA.gen(0)))
    ok = ok and ideal_dim({(0, 0): ep}, m, sq, blades) == 4
    GA.check("Mat_2(A) simple for A = C, H, Mat_2(R); not for A = R + R", ok)
    return ok


def check_block_flattening():
    ok = True
    # (m, r, (p, q) of D, dim D, dim of Mat_mr(D))
    for m, r, (p, q), dimD, total in ((2, 2, (0, 2), 4, 64), (2, 3, (0, 1), 2, 72),
                                      (3, 2, (1, 0), 2, 72)):
        sq, blades = alg(p, q)
        ok = ok and len(blades) == dimD
        # basis of Mat_m(Mat_r(D)): (i, j, a, b, blade); Phi sends it to ((i r + a), (j r + b), blade)
        B4 = [(i, j, a, c, bl) for i in range(m) for j in range(m) for a in range(r)
              for c in range(r) for bl in blades]
        phi = {e: (e[0] * r + e[2], e[1] * r + e[3], e[4]) for e in B4}
        ok = ok and len(B4) == total and len(set(phi.values())) == total
        ok = ok and set(phi.values()) == {(I, J, bl) for I in range(m * r) for J in range(m * r)
                                         for bl in blades}
        for e in B4:
            for f in B4:
                # product in Mat_m(Mat_r(D)): E_ij(E_ab d) * E_kl(E_cd d') = delta_jk delta_bc E_il(E_ad dd')
                if e[1] == f[0] and e[3] == f[2]:
                    prod = {(e[0], f[1], e[2], f[3]): GA.mul({e[4]: F(1)}, {f[4]: F(1)}, sq)}
                else:
                    prod = {}
                lhs = {}
                for (i, j, a, c), d in prod.items():
                    for bl, co in d.items():
                        lhs[(i * r + a, j * r + c)] = GA.add(lhs.get((i * r + a, j * r + c), {}),
                                                             {bl: co})
                X = {(phi[e][0], phi[e][1]): {phi[e][2]: F(1)}}
                Y = {(phi[f][0], phi[f][1]): {phi[f][2]: F(1)}}
                rhs = mmul(X, Y, sq)
                ok = ok and {k: v for k, v in lhs.items() if v} == rhs
    GA.check("block flattening Mat_m(Mat_r(D)) -> Mat_mr(D) is a multiplicative bijection", ok)
    return ok


def check_matrices_over_direct_sum():
    ok = True
    m = 2
    for (p, q), half in (((0, 3), 4), ((1, 0), 1)):
        sq, blades = alg(p, q)
        n = p + q
        omega = {tuple(range(n)): F(1)}
        ep = GA.scal(F(1, 2), GA.add(GA.sc(1), omega))
        em = GA.scal(F(1, 2), GA.sub(GA.sc(1), omega))
        ok = ok and GA.eq(GA.mul(ep, ep, sq), ep) and GA.is_zero(GA.mul(ep, em, sq))
        ok = ok and GA.eq(GA.add(ep, em), GA.sc(1))
        ok = ok and all(GA.commutes(GA.gen(g), ep, sq) for g in range(n))
        Ep, Em = ident(m, ep), ident(m, em)
        basis = mbasis(m, blades)
        # each summand eps Mat_2(A) has dimension m^2 * dim(eps A)
        for E in (Ep, Em):
            ok = ok and GA.field_rank([mcoords(mmul(E, X, sq), m, blades) for X in basis]) == m * m * half
        # Psi(X) = (eps_+ X, eps_- X): multiplicative on basis pairs, injective
        for X in basis:
            for Y in basis:
                XY = mmul(X, Y, sq)
                for E in (Ep, Em):
                    ok = ok and mmul(E, XY, sq) == mmul(mmul(E, X, sq), mmul(E, Y, sq), sq)
        joint = [mcoords(mmul(Ep, X, sq), m, blades) + mcoords(mmul(Em, X, sq), m, blades)
                 for X in basis]
        ok = ok and GA.field_rank(joint) == len(basis) == 2 * m * m * half
        if half == 4:
            # eps_+ A is a copy of H: eps_+ e1, eps_+ e2 square to -eps_+ and anticommute
            u, v = GA.mul(ep, GA.gen(0), sq), GA.mul(ep, GA.gen(1), sq)
            ok = ok and GA.eq(GA.mul(u, u, sq), GA.neg(ep)) and GA.eq(GA.mul(v, v, sq), GA.neg(ep))
            ok = ok and GA.eq(GA.mul(u, v, sq), GA.neg(GA.mul(v, u, sq)))
    GA.check("Mat_2(A1 + A2) = Mat_2(A1) + Mat_2(A2) via the central idempotents", ok)
    return ok

tower.structure-tower-c-norms:
"""tower.structure-tower-c-norms: exact checks of the algebraic part.

Complexified floors T_k^C are GA.py multivectors with Gaussian-rational (GA.QI) coefficients, in the
tower layout (ground (p,q) first, then plane j as e_j (+1), f_j (-1)). The * of the statement is
    (c e_I)* = conj(c) (-1)^(|I|(|I|-1)/2) (-1)^(#{i in I : e_i^2 = -1}) e_I .
(1) Existence and uniqueness: on every floor with m = n + 2k <= 6 (all grounds n <= 4, k <= 1, and
    n <= 2, k = 2) this formula equals the reversed product of the generator values x* = +-x (so it is
    the antiautomorphism those values determine), it is antimultiplicative on every pair of basis
    blades, conjugate-linear and antimultiplicative on complex samples, and involutive.
(2) Unitarity and adjoints: every frame blade z (all of them, m <= 8) has z* z = 1, in particular the
    ground volume u_A, the plane volumes omega_j and Omega_k; v_j* = w_j and w_j* = v_j.
(3) Compatibility of the maps: iota_k (inclusion) commutes with * (same values on the blades of
    T_k inside T_{k+1}); phi_k is a *-map: phi_k^{-1}(M)* = phi_k^{-1}(M^dagger) for every basis matrix
    a (x) E_{I,J} (M^dagger = transpose with entrywise *), using the identification exported by
    tower.compatibility-connecting-maps-transported; theta_k commutes with dagger; the correctors V_k
    and W_k (W_0 = 1, W_{k+1} = theta_k(W_k) V_k^{-1}) are unitary for k <= 2.
(4) Even p - q: the tensor-Pauli assignment (over Q(i)) of the generators (x -> Y_i if x^2 = 1,
    x -> -i Y_i if x^2 = -1) satisfies the floor's relations, carries * to the conjugate transpose on
    every blade, and the 2^m blade images are orthogonal for the trace form (Tr(M_S^dagger M_T) =
    N delta_ST, computed), hence independent, and 2^m = N^2 with N = 2^(m/2): a *-isomorphism onto
    Mat_N(C), for every even floor with m <= 6.
Not computable here: the uniqueness of the C*-norm on a full matrix algebra and the isometry of
*-monomorphisms (spectral-radius arguments of analysis); they rest on (4).
"""
from fractions import Fraction as F
from itertools import product

import GA
import fock
from tp_premise import premise

QI = GA.QI
FLOORS = [((p, n - p), k) for n in range(5) for p in range(n + 1) for k in (0, 1)
          if n + 2 * k <= 6] + [((p, n - p), 2) for n in range(3) for p in range(n + 1)]
CS1 = {(): QI(2, 1), (0,): QI(0, 3), (0, 1): QI(1, -1), (1, 2): QI(F(1, 2), 0)}
CS2 = {(1,): QI(-1, 2), (0, 2): QI(3, 0), (): QI(0, F(1, 3)), (0, 1, 2): QI(1, 1)}


def floor(p, q, k):
    return tuple([1] * p + [-1] * q + [1, -1] * k)


def star(x, S):
    out = {}
    for b, c in x.items():
        g = len(b)
        sgn = (-1) ** (g * (g - 1) // 2) * (-1) ** sum(1 for i in b if S[i] == -1)
        cc = c.conj() if isinstance(c, QI) else c
        out[b] = cc * sgn
    return {b: c for b, c in out.items() if c != 0}


def restrict(x, m):
    return {b: c for b, c in x.items() if all(i < m for i in b)}


def check_star_exists_unique_antimultiplicative():
    for (p, q), k in FLOORS:
        S = floor(p, q, k)
        m = len(S)
        gstar = [GA.scal(S[i], GA.gen(i)) for i in range(m)]
        for b in GA.all_blades(m):
            prod_ = GA.sc(1)
            for i in reversed(b):
                prod_ = GA.mul(prod_, gstar[i], S)
            assert GA.eq(star({b: F(1)}, S), prod_)
        for b1 in GA.all_blades(m):
            for b2 in GA.all_blades(m):
                x, y = {b1: F(1)}, {b2: F(1)}
                assert GA.eq(star(GA.mul(x, y, S), S), GA.mul(star(y, S), star(x, S), S))
        a, c = restrict(CS1, m), restrict(CS2, m)
        assert GA.eq(star(GA.mul(a, c, S), S), GA.mul(star(c, S), star(a, S), S))
        assert GA.eq(star(star(a, S), S), a)
        ia = {b: x * QI(0, 1) for b, x in a.items()}
        assert GA.eq(star(ia, S), {b: x * QI(0, -1) for b, x in star(a, S).items()})
    return True


def check_frame_unitary_and_ladder_adjoint():
    for p, q in [(p, n - p) for n in range(5) for p in range(n + 1)]:
        for k in range(3):
            S = floor(p, q, k)
            m = len(S)
            if m > 8:
                continue
            n = p + q
            for b in GA.all_blades(m):
                z = {b: F(1)}
                assert GA.eq(GA.mul(star(z, S), z, S), GA.sc(1))
            vols = [{tuple(range(n)): F(1)}]
            Om = GA.sc(1)
            for j in range(k):
                e, f = GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1)
                om = GA.mul(e, f, S)
                Om = GA.mul(Om, om, S)
                vols.append(om)
                v, w = GA.scal(F(1, 2), GA.add(e, f)), GA.scal(F(1, 2), GA.sub(e, f))
                assert GA.eq(star(v, S), w) and GA.eq(star(w, S), v)
                assert GA.eq(star(om, S), om)
            vols.append(Om)
            for z in vols:
                assert GA.eq(GA.mul(star(z, S), z, S), GA.sc(1))
    return True


# (ground (p, q), number of floors kk + 1) for the compatibility check
COMPAT_CASES = [((1, 1), 3), ((2, 0), 2), ((0, 2), 2), ((1, 3), 2)]
# generators added by one plane (e_j, f_j): T_k is T_(k+1) without its last two generators
PLANE_GENS = 2
# matrix-unit level at which theta is checked to commute with the dagger
THETA_LEVEL = 1


def check_maps_and_correctors_compatible():
    ex = premise("tower.compatibility-connecting-maps-transported")
    premise("tower.commuting-copies")
    premise("tower.algebraic-limit-even-charge")
    premise("transport.rule-1-morita-trivial")
    Tower, idx, theta, corrector = ex["Tower"], ex["idx"], ex["theta"], ex["corrector"]
    for (p, q), floors in COMPAT_CASES:
        T = Tower(p, q, floors)
        S = T.S
        m = len(S)
        # iota: the * of T_k is the restriction of the * of T_{k+1}
        for b in GA.all_blades(m - PLANE_GENS):
            assert GA.eq(star({b: F(1)}, S[:m - PLANE_GENS]), star({b: F(1)}, S))
        for k in range(floors):
            for a in GA.all_blades(T.n):
                for I in idx(k):
                    for J in idx(k):
                        x = T.phi_inv({(I, J): {a: F(1)}}, k)
                        dag = T.phi_inv({(J, I): star({a: F(1)}, S)}, k)
                        assert GA.eq(star(x, S), dag)
        # theta commutes with dagger, on matrix units
        for I in idx(THETA_LEVEL):
            for J in idx(THETA_LEVEL):
                M = {(I, J): GA.sc(1)}
                th = theta(M)
                thd = {(L, K): star(a, S) for (K, L), a in th.items()}
                assert thd == theta({(J, I): GA.sc(1)})
        # correctors: diagonal with entries u_A or +-1; V^dagger V = 1; W recursion stays unitary
        W = {((), ()): GA.sc(1)}
        for k in range(floors):
            V, Vi = corrector(T, k, True)
            for K, x in V.items():
                assert GA.eq(GA.mul(star(x, S), x, S), GA.sc(1))
                assert GA.eq(star(x, S), Vi[K])
            th = theta(W)
            W = {(K, L): GA.mul(a, Vi[L], S) for (K, L), a in th.items()}
            for (K, L), a in W.items():
                assert K == L and GA.eq(GA.mul(star(a, S), a, S), GA.sc(1))
        assert len(W) == 2 ** floors
    return True


def pauli_rep(m):
    """Tensor-Pauli Y_1..Y_m on (C^2)^(m/2) as monomial matrices: row i -> (column, QI entry). These are
    the Hermitian Jordan-Wigner Majoranas (sz on earlier factors; sx, sy on the mode's own factor)."""
    return [[(j, QI(c)) for (i, j), c in sorted(fock.majorana(p, m // 2, fock.MSB, kind="herm").items())]
            for p in range(2 * (m // 2))]


def mm(A, B):
    """Product of monomial matrices: (AB)[i] = B applied after A's column."""
    return [(B[A[i][0]][0], A[i][1] * B[A[i][0]][1]) for i in range(len(A))]


def dagger(A):
    out = [None] * len(A)
    for i, (j, c) in enumerate(A):
        out[j] = (i, c.conj())
    return out


def trace(A):
    return sum((c for i, (j, c) in enumerate(A) if i == j), QI(0))


def check_even_floors_are_full_matrix_star_algebras():
    for (p, q), k in FLOORS:
        if (p - q) % 2:
            continue
        S = floor(p, q, k)
        m = len(S)
        if m == 0:
            continue
        N = 2 ** (m // 2)
        Y = pauli_rep(m)
        X = [Y[i] if S[i] == 1 else [(j, c * QI(0, -1)) for j, c in Y[i]] for i in range(m)]
        ident = [(i, QI(1)) for i in range(N)]
        for i in range(m):
            assert mm(X[i], X[i]) == [(j, c * S[i]) for j, c in ident]
            for j in range(i + 1, m):
                assert mm(X[i], X[j]) == [(a, -c) for a, c in mm(X[j], X[i])]
        imgs = []
        for b in GA.all_blades(m):
            M = ident
            for i in b:
                M = mm(M, X[i])
            (bb, sgn), = star({b: F(1)}, S).items()
            assert bb == b and dagger(M) == [(j, c * sgn) for j, c in M]
            imgs.append(M)
        # trace form: Tr(M_S^dagger M_T) = N delta_ST, so the 2^m images are independent
        for a, A in enumerate(imgs):
            Ad = dagger(A)
            for bi, B in enumerate(imgs):
                assert trace(mm(Ad, B)) == (QI(N) if a == bi else QI(0))
        assert len(imgs) == 2 ** m == N * N
    return True

tower.volume-elements-planes:
"""tower.volume-elements-planes: exact checks.

Floor T_k over the ground Cl(p,q), in GA.py's blade engine with the layout of the tower: indices
0..n-1 are the ground generators (p squaring +1, then q squaring -1), and plane j (j = 1..k)
occupies indices n + 2(j-1) (e_j, square +1) and n + 2j - 1 (f_j, square -1). Computed for every
ground with n = p + q <= 3 (degenerate grounds excluded, as in the tower) and every k <= 3:
(1) omega_j = e_j f_j squares to 1, anticommutes with e_j and f_j, commutes with every ground
    generator and every generator of another plane, and the omega_j commute pairwise;
(2) Omega_k = omega_1 ... omega_k squares to 1, commutes with every ground generator and
    anticommutes with every plane generator e_j, f_j (j <= k).
Each statement is tested as an exact multivector identity, with a control: omega_j does NOT
commute with its own plane, and Omega_k does NOT commute with a plane generator.
"""
import GA

GROUNDS = [(p, q) for n in range(4) for p in range(n + 1) for q in [n - p]]
KS = [1, 2, 3]


def floor(p, q, k):
    return tuple([1] * p + [-1] * q + [1, -1] * k)


def plane(n, j):
    """Generators (e_j, f_j) of plane j (1-based)."""
    return GA.gen(n + 2 * (j - 1)), GA.gen(n + 2 * j - 1)


def plane_labels(k):
    """The labels 1..k of the planes of floor k."""
    return range(1, k + 1)


def check_plane_volume_elements():
    for p, q in GROUNDS:
        n = p + q
        for k in KS:
            S = floor(p, q, k)
            oms = []
            for j in plane_labels(k):
                e, f = plane(n, j)
                om = GA.mul(e, f, S)
                oms.append(om)
                assert GA.eq(GA.mul(om, om, S), GA.sc(1)), (p, q, k, j)
                # anticommutes with its own plane, and does not commute with it
                for g in (e, f):
                    assert GA.anticommutes(om, g, S)
                    assert not GA.commutes(om, g, S)
                # commutes with every ground generator and every other plane's generators
                others = [GA.gen(i) for i in range(n)]
                for i in plane_labels(k):
                    if i != j:
                        others.extend(plane(n, i))
                for g in others:
                    assert GA.commutes(om, g, S), (p, q, k, j)
            for a in oms:
                for b in oms:
                    assert GA.commutes(a, b, S)
    return True


def check_product_omega_k():
    for p, q in GROUNDS:
        n = p + q
        for k in KS:
            S = floor(p, q, k)
            Om = GA.sc(1)
            for j in range(1, k + 1):
                e, f = plane(n, j)
                Om = GA.mul(Om, GA.mul(e, f, S), S)
            # Omega_k is the product of the 2k plane letters: a blade of grade 2k
            assert list(Om.keys()) == [tuple(range(n, n + 2 * k))]
            assert GA.eq(GA.mul(Om, Om, S), GA.sc(1)), (p, q, k)
            for i in range(n):
                assert GA.commutes(Om, GA.gen(i), S)
            for j in range(1, k + 1):
                for g in plane(n, j):
                    assert GA.anticommutes(Om, g, S)
                    assert not GA.commutes(Om, g, S)
    return True
